<include file="Public:header"/><link rel="stylesheet" href="{pigcms{$static_path}css/bootstrap.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/font-awesome.min.css?t=01"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-fonts.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace.min.css" id="main-ace-style"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-skins.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-rtl.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/global.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui-timepicker-addon.css"><link rel="stylesheet" href="{pigcms{$static_public}layui/css/layui.css"  media="all">	<div class="mainbox">         <div style="margin-left: 10px;color: #9a9999;">            <span> 说明：</span>          <p>1、以当前用户选择小区为中心，推荐最近的商业商品</p>          <p>2、优先推荐外卖、团购类型的商品，最后推荐预约服务的商品</p>        </div>       <div class="tabbable" style="height: 60px;">        </div>      <div id="basicinfo_div" class="tab_div" >        <input type="hidden" class="input set_input" name="block_type_id" value="guess_you_like_goods"/>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>是否展示</label></label>            <div class="radio" style="padding-top: 5px;">                <label style="padding-left:0px;padding-right:20px;"><input name="is_show" value="1" type="radio" class="ace set_input"  <if condition="$nav_set AND $nav_set.is_show eq 1">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;开启展示</span></label>                <label style="padding-left:0px;"><input name="is_show" value="0" type="radio" class="ace set_input" <if condition="empty($nav_set) OR ($nav_set AND $nav_set.is_show eq 0)">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;关闭展示</span></label>            </div>        </div>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label class="red">*商品显示数量：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="number" class="input set_input" id="set_input_num" name="set_num" value="{pigcms{$nav_set['set_num']}" placeholder="设置每个商家的最大推荐数量" max="9999" min="1" oninput="this.value = this.value.replace(/[^0-9]/g, '');"  required style="width: 220px;"> &nbsp;&nbsp;&nbsp;1、设置每个商家的最大推荐数量，2、按商业商品位置给用户推荐            </div>        </div>            <if condition="!$house_visualize_assign">            <div style="text-align:center;margin-top: 50px;">               <button type="button" onclick="saveLikeGoodsSetData()" class="ant-btn ant-btn-primary" >保存设置</button>           </div>           </if>        </div>	</div><style type="text/css">    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }   .input{ width: 300px;height: 30px;    line-height: 30px;}    .right_div{        display: inline-block;    margin-left: 50px;    }    .ant-btn {        line-height: 1.499;        position: relative;        display: inline-block;        font-weight: 400;        white-space: nowrap;        text-align: center;        background-image: none;        border: 1px solid transparent;        -webkit-box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        cursor: pointer;        -webkit-transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        -webkit-user-select: none;        -moz-user-select: none;        -ms-user-select: none;        user-select: none;        -ms-touch-action: manipulation;        touch-action: manipulation;        height: 32px;        padding: 0 15px;        font-size: 14px;        border-radius: 2px;        color: #fff;        background-color: #1890ff;        text-shadow: 0 -1px 0 rgb(0 0 0 / 12%);}</style><script type="text/javascript" charset="utf-8">   function saveLikeGoodsSetData(){       var set_num=$('#set_input_num').val();       set_num=$.trim(set_num);       set_num=set_num ? parseInt(set_num):0;        if(isNaN(set_num) || !set_num || set_num<1){            layer.alert('商品显示数量设置错误！ ');            return false;       }       var inputArr=$('#basicinfo_div .set_input').serializeArray();       $.post("{pigcms{:U('save_guess_you_like_goods')}",inputArr,function(result){            if(result.status != 1){                layer.alert('保存失败,请重试~ ');            }else{                layer.alert('保存成功！');            }        },'json');   }</script><include file="Publics:footer"/>